<div class="page-head"><div><h1><?= te('Join our talent pool') ?></h1><p class="sub"><?= te('Apply for future opportunities without choosing a current requisition.') ?></p></div></div>
<form class="card" method="post" enctype="multipart/form-data"><?= csrf_field() ?><label><?= te('Full name') ?><input name="name" maxlength="190" required autocomplete="name"></label><label><?= te('Email') ?><input name="email" type="email" required maxlength="190" autocomplete="email"></label><label><?= te('Phone') ?><input name="phone" maxlength="40" autocomplete="tel"></label><label><?= te('Resume · PDF or DOCX, maximum 5 MB') ?><input name="resume" type="file" accept=".pdf,.docx"></label><label><input class="w-auto" name="consent" type="checkbox" required> <?= te('I authorize the hiring agency to review my application and contact me about opportunities.') ?></label> <a href="/privacy" target="_blank" rel="noopener"><?= te('Read the privacy notice') ?></a><button class="btn"><?= te('Apply') ?></button></form>
